using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Playables;using UnityEngine.SceneManagement;using UnityEngine.Timeline;using Valve.VR;
[InitializeOnLoad]public static class Scene05HomecomingSetup
{
 const string Dir="Assets/Scene05HomecomingAnimation";
 static Scene05HomecomingSetup(){EditorApplication.delayCall+=Run;}
 [MenuItem("Project3D/Scene05/Build homecoming story")]
 public static void Run(){if(File.Exists("Temp/scene05-build.done")||EditorApplication.isPlaying)return;var scene=SceneManager.GetActiveScene();if(scene.name!="scene_05")return;try{if(scene.GetRootGameObjects().Any(g=>g.name=="Scene05_Homecoming")){File.Copy("Logs/scene_05_before_homecoming.unity",Dir+"/Recovery.unity",true);AssetDatabase.ImportAsset(Dir+"/Recovery.unity");scene=EditorSceneManager.OpenScene(Dir+"/Recovery.unity");EditorSceneManager.SaveScene(scene,"Assets/Project3D/Scenes/scene_05.unity");}Build(scene);File.WriteAllText("Temp/scene05-build.done","OK");}catch(Exception e){File.WriteAllText("Temp/scene05-build.error",e.ToString());Debug.LogException(e);}}
 static Material Mat(string name,Color color){var path=Dir+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Standard"));m.color=color;AssetDatabase.CreateAsset(m,path);}return m;}
 static GameObject Cube(string name,Transform parent,Vector3 pos,Vector3 size,Material mat,bool collider=false){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;if(!collider)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static TextMesh Text(string name,Transform parent,string value,Vector3 at,float size){var g=new GameObject(name,typeof(TextMesh));g.transform.SetParent(parent,false);g.transform.localPosition=at;var t=g.GetComponent<TextMesh>();t.text=value;t.fontSize=48;t.characterSize=size;t.anchor=TextAnchor.MiddleCenter;t.alignment=TextAlignment.Center;t.color=new Color(.16f,.14f,.10f);g.AddComponent<Scene05DocumentLabel>();return t;}
 static GameObject Document(bool open){var g=new GameObject(open?"Taiwan Compatriot Travel Certificate - open":"Taiwan Compatriot Travel Certificate - closed");var paper=Mat("DocumentPaper",new Color(.90f,.83f,.65f));Cube("Paper",g.transform,Vector3.zero,new Vector3(open?.30f:.15f,.21f,.004f),paper);Text("Document text",g.transform,open?"台湾同胞旅行证明\n\n持证人：父亲\n事由：返乡探亲\n\n离乡近四十年，终于等到归期。\n\n1988年｜叙事重构道具":"台湾同胞\n旅行证明\n\n返乡探亲\n1988",new Vector3(0,0,-.003f),open?.0065f:.008f);var asset=PrefabUtility.SaveAsPrefabAsset(g,Dir+(open?"/TravelCertificate_Open.prefab":"/TravelCertificate_Closed.prefab"));UnityEngine.Object.DestroyImmediate(g);return asset;}
 static AudioClip Audio(string name)=>AssetDatabase.LoadAssetAtPath<AudioClip>(Dir+"/"+name+".mp3");
 static void Build(Scene scene)
 {
  Directory.CreateDirectory(Dir);EditorSceneManager.SaveScene(scene,"Logs/scene_05_before_homecoming.unity",true);
  var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();Func<string,Transform> find=n=>all.First(t=>t.name==n);
  if(all.Any(t=>t.name=="Scene05_Homecoming"))throw new Exception("Scene05 already built");
  var root=new GameObject("Scene05_Homecoming");var story=root.AddComponent<Scene05HomecomingStory>();story.director=root.AddComponent<PlayableDirector>();story.director.playOnAwake=false;story.director.extrapolationMode=DirectorWrapMode.Hold;
  story.father=find("Father_Elder");foreach(var a in story.father.GetComponentsInChildren<Animator>(true))a.enabled=false;foreach(var p in story.father.GetComponentsInChildren<IncenseCharacters.IncenseCharacterPlayer>(true))p.enabled=false;
  foreach(var t in story.father.GetComponentsInChildren<Transform>(true))if(t!=story.father&&t.name!="CharacterMesh")t.localRotation=Quaternion.identity;
  story.father.position=new Vector3(-.72f,.15f,-4.02f);story.father.rotation=Quaternion.identity;
  story.burner=find("censer");story.burner.position=new Vector3(-.72f,.93f,-3.30f);
  find("tea_set").position=new Vector3(-1.13f,.93f,-2.95f);
  // Clear the departure side of the table, keeping the stools in the room.
  find("stool_2").position=new Vector3(-1.85f,.15f,-4.1f);find("stool_3").position=new Vector3(-1.85f,.15f,-4.55f);
  var bag=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Project3D/Prefabs/prop/suitcase.prefab"));bag.name="Scene05_FatherLuggage";bag.transform.SetParent(root.transform,true);bag.transform.SetPositionAndRotation(new Vector3(-.24f,.15f,-4.06f),Quaternion.Euler(-90,0,0));story.luggage=bag.transform;
  var bb=PermitInspection.BoundsOf(bag);story.luggageHandle=new GameObject("Luggage handle grip").transform;story.luggageHandle.SetParent(bag.transform,true);story.luggageHandle.position=new Vector3(bb.center.x,bb.max.y-.025f,bb.center.z);
  story.touchPoint=new Vector3(-.72f,1.065f,-3.398f);
  // A front door with a real hinge; it closes after the actor has crossed the threshold.
  var hinge=new GameObject("Scene05_FrontDoorHinge");hinge.transform.SetParent(root.transform,false);hinge.transform.position=new Vector3(-.65f,.15f,-5.48f);story.door=hinge.transform;
  var wood=Mat("FrontDoorWood",new Color(.26f,.16f,.085f));Cube("Front door",hinge.transform,new Vector3(.65f,1.05f,0),new Vector3(1.30f,2.1f,.065f),wood,true);Cube("Door handle",hinge.transform,new Vector3(1.13f,1.0f,.075f),new Vector3(.10f,.035f,.04f),Mat("DoorHandle",new Color(.45f,.32f,.14f)));
  var closed=Document(false);var open=Document(true);var doc=(GameObject)PrefabUtility.InstantiatePrefab(closed);doc.name="Scene05_台湾同胞旅行证明";doc.transform.SetParent(root.transform,true);doc.transform.SetPositionAndRotation(new Vector3(-1.05f,.939f,-2.68f),Quaternion.Euler(90,0,0));
  var hit=doc.AddComponent<BoxCollider>();hit.size=new Vector3(.17f,.23f,.018f);var glow=doc.AddComponent<SoftInteractionHighlight>();
  story.permit=root.AddComponent<PermitInspection>();story.permit.enabled=false;story.permit.homecoming=story;story.permit.tableModel=doc.transform;story.permit.tableCollider=hit;story.permit.tableGlow=glow;story.permit.closedPrefab=closed;story.permit.openPrefab=open;story.permit.RequiredReadSeconds=3;story.permit.enabled=true;
  var itinerary=new GameObject("Scene05_行程单");itinerary.transform.SetParent(root.transform,false);itinerary.transform.SetPositionAndRotation(new Vector3(-.57f,.939f,-2.68f),Quaternion.Euler(90,0,0));Cube("Itinerary paper",itinerary.transform,Vector3.zero,new Vector3(.22f,.27f,.004f),Mat("DocumentPaper",Color.white));Text("Itinerary",itinerary.transform,"返乡探亲 · 行程单\n\n台湾 → 香港 → 故乡\n\n随身行李已备妥\n证件留桌，待归时再叙\n\n1988年｜叙事重构",new Vector3(0,0,-.004f),.006f);
  story.rig=find("[CameraRig]");story.headsetCamera=story.rig.GetComponentInChildren<Camera>(true);story.headsetCamera.nearClipPlane=.025f;
  var body=story.rig.GetComponent<CharacterController>();if(!body)body=story.rig.gameObject.AddComponent<CharacterController>();body.height=1.7f;body.center=new Vector3(0,.85f,0);body.radius=.18f;body.skinWidth=.02f;
  story.movement=story.rig.gameObject.AddComponent<MuseumLeftStickMove>();story.movement.enabled=false;story.movement.headset=story.headsetCamera.transform;story.movement.leftHand=story.rig.GetComponentsInChildren<SteamVR_Behaviour_Pose>(true).First(p=>p.inputSource==SteamVR_Input_Sources.LeftHand);
  story.turning=story.rig.gameObject.AddComponent<MuseumRightStickTurn>();story.turning.enabled=false;story.turning.headset=story.headsetCamera.transform;story.turning.rightHand=story.rig.GetComponentsInChildren<SteamVR_Behaviour_Pose>(true).First(p=>p.inputSource==SteamVR_Input_Sources.RightHand);story.turning.snapTurn=true;story.turning.snapDegrees=15;
  var desktop=new GameObject("Scene05 Desktop Preview");desktop.transform.SetParent(root.transform,false);story.desktopRig=desktop.transform;var dc=desktop.AddComponent<CharacterController>();dc.height=1.7f;dc.center=new Vector3(0,.85f,0);dc.radius=.18f;
  var head=new GameObject("Camera");head.transform.SetParent(desktop.transform,false);head.transform.localPosition=new Vector3(0,1.57f,0);story.desktopCamera=head.AddComponent<Camera>();story.desktopCamera.nearClipPlane=.025f;story.desktopCamera.fieldOfView=80;head.AddComponent<AudioListener>();story.desktopMovement=desktop.AddComponent<DesktopMuseumDriver>();story.desktopMovement.head=head.transform;story.desktopMovement.showHud=false;story.desktopMovement.enabled=false;
  var hands=new System.Collections.Generic.List<Transform>();var skin=Mat("ViewerHands",new Color(.65f,.44f,.30f));
  foreach(bool left in new[]{true,false}){hands.Add(Hand(left, left?story.movement.leftHand.transform:story.turning.rightHand.transform,skin,new Vector3(0,-.025f,.06f)));hands.Add(Hand(left,head.transform,skin,new Vector3(left?-.24f:.24f,-.29f,.43f)));}story.hands=hands.ToArray();
  foreach(var h in story.hands)h.gameObject.SetActive(false);
  foreach(var tour in all.Select(t=>t.GetComponent<MuseumSceneTour>()).Where(t=>t))tour.enabled=false;
  foreach(var f in find("scene_05").GetComponentsInChildren<MeshFilter>(true)){if(!f.sharedMesh||f.GetComponent<Collider>()||f.name=="sea")continue;if(f.name=="rowhouse_1960"||f.name=="ground"||f.transform.position.magnitude<8){var c=f.gameObject.AddComponent<MeshCollider>();c.sharedMesh=f.sharedMesh;}}
  story.prayer=Audio("Father_Prayer");story.expectation=Audio("Burner_Expectant");story.leave=Audio("Father_Leave");story.home=Audio("Father_Home");story.finalVoice=Audio("Burner_Return");story.chime=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Scene01Animation/航海顺利_轻叮.wav");
  story.chimeAt=story.prayerAt+story.prayer.length*.73f;
  story.doorSound=Sound("DoorClose",.35f,0);story.ticking=Sound("ClockTick",1,1);
  var stepPath=AssetDatabase.FindAssets("t:AudioClip").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.Contains("较轻脆的木地板走动"));if(stepPath!=null)story.footsteps=AssetDatabase.LoadAssetAtPath<AudioClip>(stepPath);
  story.CapturePose();var timeline=ScriptableObject.CreateInstance<TimelineAsset>();timeline.name="Scene05 1988 Return Home";AssetDatabase.CreateAsset(timeline,Dir+"/Scene05_Homecoming.playable");var track=timeline.CreateTrack<Scene05HomecomingTrack>(null,"父亲祈愿 → 抚炉告别 → 提箱出门 → 关门与自由探索");var clip=track.CreateDefaultClip();clip.start=0;clip.duration=40;clip.displayName="1988年｜返乡探亲";story.director.playableAsset=timeline;story.director.SetGenericBinding(track,story);story.Sample(0);
  EditorUtility.SetDirty(story);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
 }
 static Transform Hand(bool left,Transform parent,Material mat,Vector3 at){var g=new GameObject(left?"Scene05 Left Hand":"Scene05 Right Hand");g.transform.SetParent(parent,false);g.transform.localPosition=at;Cube("Palm",g.transform,Vector3.zero,new Vector3(.075f,.025f,.085f),mat);for(int i=0;i<4;i++){var f=GameObject.CreatePrimitive(PrimitiveType.Capsule);f.name="Finger";f.transform.SetParent(g.transform,false);f.transform.localPosition=new Vector3((i-1.5f)*.018f,0,.065f);f.transform.localRotation=Quaternion.Euler(90,0,0);f.transform.localScale=new Vector3(.014f,.032f,.014f);f.GetComponent<Renderer>().sharedMaterial=mat;UnityEngine.Object.DestroyImmediate(f.GetComponent<Collider>());}Cube("Thumb",g.transform,new Vector3(left?.045f:-.045f,0,.015f),new Vector3(.022f,.023f,.055f),mat);return g.transform;}
 static AudioClip Sound(string name,float duration,int type){int rate=22050,n=(int)(rate*duration);var random=new System.Random(5);using(var m=new MemoryStream())using(var w=new BinaryWriter(m)){w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));w.Write(36+n*2);w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(rate);w.Write(rate*2);w.Write((short)2);w.Write((short)16);w.Write(System.Text.Encoding.ASCII.GetBytes("data"));w.Write(n*2);for(int i=0;i<n;i++){double t=i/(double)rate,v=type==0?((random.NextDouble()*2-1)*.5+Math.Sin(t*2*Math.PI*95)*.5)*Math.Exp(-t*22):t<.045?Math.Sin(t*2*Math.PI*1800)*Math.Exp(-t*130):0;w.Write((short)(v*10000));}File.WriteAllBytes(Dir+"/"+name+".wav",m.ToArray());}AssetDatabase.ImportAsset(Dir+"/"+name+".wav");return AssetDatabase.LoadAssetAtPath<AudioClip>(Dir+"/"+name+".wav");}
}


